const pedidos = items.filter(i => i.json.__kind === 'pedido');
const logs = items.filter(i => i.json.__kind === 'log');
const sent = new Set(logs.filter(i => i.json.Evento === 'preparation_email' && i.json.Resultado === 'Enviado').map(i => String(i.json['N.º de orden'] ?? '').trim()));
return pedidos.filter(i => i.json.Estado === 'En preparación').map(i => {
  const key = Object.keys(i.json).find(k => k.normalize('NFC').trim() === 'N.º de orden');
  const order = String(key ? i.json[key] : '').trim();
  if (!order || sent.has(order)) return null;
  const json = { ...i.json, 'N.º de orden': order, NumeroOrden: order };
  delete json.__kind;
  return { json };
}).filter(Boolean);

