const pedidos = items.filter(i => i.json.__kind === 'pedido');
const logs = items.filter(i => i.json.__kind === 'log');
const existing = new Set(logs.filter(i => i.json.Evento === 'review_request' && ['Pendiente','Enviado'].includes(i.json.Resultado)).map(i => String(i.json['N.º de orden'] ?? '').trim()));
return pedidos.filter(i => i.json.Estado === 'Entregado').map(i => {
  const key = Object.keys(i.json).find(k => k.normalize('NFC').trim() === 'N.º de orden');
  const order = String(key ? i.json[key] : '').trim();
  if (!order || existing.has(order)) return null;
  return { json: { Fecha: new Date().toISOString(), 'N.º de orden': order, Evento: 'review_request', 'Estado detectado': 'Entregado', Correo: i.json.Correo ?? '', 'Fecha envío': '', Resultado: 'Pendiente', 'Message ID': '', Notas: 'Esperando 48 horas antes de solicitar review' } };
}).filter(Boolean);

const pedidos = items.filter(i => i.json.__kind === 'pedido');
const logs = items.filter(i => i.json.__kind === 'log');
const sent = new Set(logs.filter(i => i.json.Evento === 'review_request' && i.json.Resultado === 'Enviado').map(i => String(i.json['N.º de orden'] ?? '').trim()));
const cutoff = Date.now() - 48 * 60 * 60 * 1000;
const pending = logs.filter(i => i.json.Evento === 'review_request' && i.json.Resultado === 'Pendiente' && Date.parse(i.json.Fecha) <= cutoff);
const byOrder = new Map(pedidos.map(i => [String(i.json['N.º de orden'] ?? '').trim(), i.json]));
return pending.map(i => {
  const order = String(i.json['N.º de orden'] ?? '').trim();
  const pedido = byOrder.get(order);
  if (!pedido || pedido.Estado !== 'Entregado' || sent.has(order)) return null;
  const products = [];
  if (Number(pedido['Cantidad Pan Blanco'] ?? 0) > 0) products.push('Pan Blanco');
  if (Number(pedido['Cantidad Pan Semi Integral'] ?? 0) > 0) products.push('Pan Semi Integral');
  const product = products.join(' + ') || 'Producto no identificado';
  const query = ['usp=pp_url','entry.950326924='+encodeURIComponent(order),'entry.1893454218='+encodeURIComponent(pedido.Nombre ?? ''),'entry.1903981963='+encodeURIComponent(product),'entry.732910652='+encodeURIComponent(pedido.Correo ?? '')].join('&');
  return { json: { ...pedido, NumeroOrden: order, Producto: product, ReviewURL: 'https://docs.google.com/forms/d/e/example-form-id/viewform?' + query } };
}).filter(Boolean);
